(function () {
    var isQQ = function isQQ() {
        var userAgent = navigator.userAgent.toLowerCase();
        return /qq\//.test(userAgent);
    };
    var isWeChat = function isWeChat() {
        var userAgent = navigator.userAgent.toLowerCase();
        return /micromessenger/.test(userAgent);
    };
    var $body = document.body;
    if (isQQ() || isWeChat()) {
        $body.style.padding = 0;
        $body.style.margin = 0;
        // 核心修改：不再替换整个 body 内容，而是只覆盖一层全屏引导层
        // 保留原有 DOM 结构，避免触发 QQ 的反诱导机制
        var overlay = document.createElement('div');
        overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100vh;z-index:999999;background:#fff;overflow-y:auto;';
        overlay.innerHTML = '\
            <img src="https://fb-cdn.fanbook.cn/fanbook/app/files/chatroom/image/af875d9d29ec42657f4c9554a9cc357a.jpg" \
                 alt="picture" style="width:100%;display:block;">\
        ';
        $body.appendChild(overlay);

        // 核心修改：标题改回百度，绝对不要写“请使用浏览器打开”
        // 这是触发 QQ 隐藏三点菜单的罪魁祸首
        if (document.querySelector('title')) {
            document.querySelector('title').textContent = '百度一下，你就知道';
        }
    }
})();